import {api} from './api.js';
const form=document.querySelector('#admin-login-form'),feedback=document.querySelector('#login-feedback'),button=form.querySelector('[type="submit"]'),label=document.querySelector('#login-button-label'),toggle=document.querySelector('#toggle-password'),password=form.elements.password;
api('/api/auth/me').then(({user})=>{if(user.role==='admin')location.replace('/admin')}).catch(()=>{});
toggle.onclick=()=>{const visible=password.type==='password';password.type=visible?'text':'password';toggle.setAttribute('aria-pressed',String(visible));toggle.setAttribute('aria-label',visible?'إخفاء كلمة المرور':'إظهار كلمة المرور')};
form.onsubmit=async e=>{e.preventDefault();if(button.disabled)return;feedback.hidden=true;password.removeAttribute('aria-invalid');button.disabled=true;button.setAttribute('aria-busy','true');label.textContent='جارٍ تسجيل الدخول…';try{await api('/api/auth/admin-login',{username:form.elements.username.value.trim(),password:password.value,remember:form.elements.remember.checked});location.replace('/admin')}catch(error){feedback.textContent=error.message;feedback.hidden=false;password.value='';password.setAttribute('aria-invalid','true');password.setAttribute('aria-describedby','login-feedback');password.focus()}finally{button.disabled=false;button.removeAttribute('aria-busy');label.textContent='تسجيل الدخول'}};
form.elements.username.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();if(form.elements.username.reportValidity())password.focus()}});
form.addEventListener('input',()=>{feedback.hidden=true;password.removeAttribute('aria-invalid');password.removeAttribute('aria-describedby')});
